attempts.query:
PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
SELECT (COUNT(DISTINCT ?tr) AS ?n) WHERE {
  ?tr a oncologia:Trial ; oncologia:status ?st ; oncologia:testsDrug ?d .
  ?d oncologia:name "PEMBROLIZUMAB" .
  FILTER(?st IN ("RECRUITING", "ACTIVE_NOT_RECRUITING", "NOT_YET_RECRUITING", "ENROLLING_BY_INVITATION"))
}
